const raw = $json;
const source = $('Parse Payload Demo').item.json;
let r = '';
if (raw.responses && Array.isArray(raw.responses) && raw.responses.length > 0) {
  r = String(raw.responses[0].output || '');
} else if (raw.output) {
  r = String(raw.output);
} else if (raw.choices && raw.choices[0]) {
  r = raw.choices[0].message.content;
} else if (raw.response) {
  r = String(raw.response);
} else if (raw.text) {
  r = String(raw.text);
}
if (!r) r = 'Vou verificar e ja te retorno!';
r = r.replace(/\[BOOKING_(?:REQUEST|CONFIRM)\]\s*\n?{[\s\S]*?}/gi, '').trim();
return [{ json: { ...source, tessResponse: r } }];

const KEY = $env.TRINKS_API_KEY;
const EID = String($env.TRINKS_SALON_ID || '');
const BASE = $env.TRINKS_API_BASE_URL || 'https://api.trinks.com/v1';
const h = { 'X-Api-Key': KEY, 'estabelecimentoId': EID };

// Fetch next 5 business days (skip Sun=0, Mon=1)
function getNextBusinessDays(count) {
  const dates = [];
  const d = new Date();
  while (dates.length < count) {
    const day = d.getDay();
    if (day !== 0 && day !== 1) dates.push(d.toISOString().split('T')[0]);
    d.setDate(d.getDate() + 1);
  }
  return dates;
}

const businessDays = getNextBusinessDays(5);
let slots = '';
for (const date of businessDays) {
  try {
    const r = await fetch(BASE + '/agendamentos/profissionais/' + date, { headers: h });
    const json = await r.json();
    if (json.data && Array.isArray(json.data)) {
      const avail = json.data.filter(p => p.horariosVagos && p.horariosVagos.length > 0);
      if (avail.length > 0) {
        slots += 'HORARIOS VAGOS ' + date + ':\n';
        for (const p of avail) {
          slots += '- ' + p.nome + ': ' + p.horariosVagos.join(', ') + '\n';
        }
      } else {
        slots += 'HORARIOS VAGOS ' + date + ': Nenhum disponivel.\n';
      }
    }
  } catch (e) {
    slots += 'HORARIOS ' + date + ': Erro ao consultar.\n';
  }
}
if (!slots) slots = 'HORARIOS: Erro ao consultar. Peca ao cliente o dia desejado.';

let profs = '';
try {
  const r2 = await fetch(BASE + '/profissionais', { headers: h });
  const profsData = await r2.json();
  if (profsData && profsData.data && Array.isArray(profsData.data)) {
    profs = 'PROFISSIONAIS ATIVOS:\n';
    for (const p of profsData.data) {
      profs += '- ' + (p.apelido || p.nome) + ' (ID ' + p.id + ')\n';
    }
  } else {
    profs = 'PROFISSIONAIS: Erro ao consultar.';
  }
} catch (e) {
  profs = 'PROFISSIONAIS: Erro ao consultar.';
}

const datesNote = 'DATAS COM DADOS: ' + businessDays.join(', ') + '. Para outra data, pergunte qual dia o cliente prefere.';
const source = $input.item.json;
return [{ json: { ...source, dynamicContext: datesNote + '\n\n' + slots + '\n' + profs } }];
